func computeBinary(preds []NormPrediction) EvalResult {
    classes := collectClasses(preds, true)
    if len(classes) != 2 {
        return EvalResult{Metrics: zeroMetrics(metricOrderForTask("binary_classification")), MetricOrder: metricOrderForTask("binary_classification"), ConfusionMatrix: makeConfusionMatrix(preds, classes)}
    }
    pos := classes[1]
    neg := classes[0]
    tp, fp, fn, tn := 0, 0, 0, 0
    for _, p := range preds {
        ap := p.ActualStr == pos
        pp := p.PredictedStr == pos
        switch {
        case ap && pp:
            tp++
        case !ap && pp:
            fp++
        case ap && !pp:
            fn++
        default:
            tn++
        }
    }
    total := len(preds)
    accuracy := safeDivInt(tp+tn, total)
    precision := safeDivInt(tp, tp+fp)
    recall := safeDivInt(tp, tp+fn)
    f1 := safeDiv(2*precision*recall, precision+recall)
    auc := aucROC(preds, pos)
    ll := logLoss(preds, pos)
    metrics := map[string]float64{
        "accuracy": accuracy,
        "precision": precision,
        "recall": recall,
        "f1": f1,
        "auc_roc": auc,
        "log_loss": ll,
    }
    return EvalResult{Metrics: metrics, MetricOrder: metricOrderForTask("binary_classification"), ConfusionMatrix: makeConfusionMatrix(preds, classes)}
}

func aucROC(preds []NormPrediction, pos string) float64 {
    totalPos := 0
    totalNeg := 0
    type sample struct {
        p float64
        y int
    }
    samples := make([]sample, 0, len(preds))
    for _, pr := range preds {
        y := 0
        if pr.ActualStr == pos {
            y = 1
            totalPos++
        } else {
            totalNeg++
        }
        p := 0.0
        if v, ok := pr.Probabilities[pos]; ok {
            p = v
        }
        samples = append(samples, sample{p: p, y: y})
    }
    if totalPos == 0 || totalNeg == 0 {
        return 0
    }
    sort.SliceStable(samples, func(i, j int) bool {
        if samples[i].p != samples[j].p {
            return samples[i].p > samples[j].p
        }
        return samples[i].y > samples[j].y
    })
    points := []struct{ fpr, tpr float64 }{{0, 0}}
    cumTP := 0
    cumFP := 0
    for _, s := range samples {
        if s.y == 1 {
            cumTP++
        } else {
            cumFP++
        }
        tpr := float64(cumTP) / float64(totalPos)
        fpr := float64(cumFP) / float64(totalNeg)
        points = append(points, struct{ fpr, tpr float64 }{fpr, tpr})
    }
    auc := 0.0
    for i := 1; i < len(points); i++ {
        auc += (points[i].fpr - points[i-1].fpr) * (points[i].tpr + points[i-1].tpr) / 2
    }
    return auc
}

func logLoss(preds []NormPrediction, pos string) float64 {
    if len(preds) == 0 {
        return 0
    }
    sum := 0.0
    for _, pr := range preds {
        y := 0.0
        if pr.ActualStr == pos {
            y = 1.0
        }
        p := 0.0
        if v, ok := pr.Probabilities[pos]; ok {
            p = v
        }
        p = math.Min(1-1e-15, math.Max(1e-15, p))
        sum += y*math.Log(p) + (1-y)*math.Log(1-p)
    }
    return -sum / float64(len(preds))
}

func makeConfusionMatrix(preds []NormPrediction, classes []string) *ConfusionMatrixReport {
    if len(classes) == 0 {
        return nil
    }
    idx := make(map[string]int)
    for i, c := range classes {
        idx[c] = i
    }
    matrix := make([][]int, len(classes))
    for i := range matrix {
        matrix[i] = make([]int, len(classes))
    }
    for _, p := range preds {
        ai, ok := idx[p.ActualStr]
        if !ok {
            continue
        }
        pi, ok2 := idx[p.PredictedStr]
        if !ok2 {
            continue
        }
        matrix[ai][pi]++
    }
    return &ConfusionMatrixReport{Classes: classes, Matrix: matrix}
}

func computeMulticlass(preds []NormPrediction) EvalResult {
    classes := collectClasses(preds, true)
    if len(classes) < 3 {
        return EvalResult{Metrics: zeroMetrics(metricOrderForTask("multiclass_classification")), MetricOrder: metricOrderForTask("multiclass_classification"), ConfusionMatrix: makeConfusionMatrix(preds, classes)}
    }
    total := len(preds)
    correct := 0
    type counts struct{ tp, fp, fn, tn, support int }
    perClass := make(map[string]counts)
    for _, c := range classes {
        perClass[c] = counts{}
    }
    for _, p := range preds {
        if p.ActualStr == p.PredictedStr {
            correct++
        }
        pc := perClass[p.ActualStr]
        pc.support++
        perClass[p.ActualStr] = pc
        for _, c := range classes {
            tp, fp, fn, tn := 0, 0, 0, 0
            actualC := p.ActualStr == c
            predC := p.PredictedStr == c
            if actualC && predC {
                tp = 1
            } else if !actualC && predC {
                fp = 1
            } else if actualC && !predC {
                fn = 1
            } else {
                tn = 1
            }
            pc := perClass[c]
            pc.tp += tp
            pc.fp += fp
            pc.fn += fn
            pc.tn += tn
            perClass[c] = pc
        }
    }
    sumTP, sumFP, sumFN := 0, 0, 0
    precisions := make([]float64, len(classes))
    recalls := make([]float64, len(classes))
    f1s := make([]float64, len(classes))
    supports := make([]int, len(classes))
    perClassMetrics := make(map[string]PerClassMetric)
    for i, c := range classes {
        pc := perClass[c]
        sumTP += pc.tp
        sumFP += pc.fp
        sumFN += pc.fn
        supports[i] = pc.support
        precisions[i] = safeDivInt(pc.tp, pc.tp+pc.fp)
        recalls[i] = safeDivInt(pc.tp, pc.tp+pc.fn)
        f1s[i] = safeDiv(2*precisions[i]*recalls[i], precisions[i]+recalls[i])
        perClassMetrics[c] = PerClassMetric{Precision: precisions[i], Recall: recalls[i], F1: f1s[i], Support: pc.support}
    }
    accuracy := safeDivInt(correct, total)
    precisionMicro := safeDivInt(sumTP, sumTP+sumFP)
    recallMicro := safeDivInt(sumTP, sumTP+sumFN)
    f1Micro := safeDiv(2*precisionMicro*recallMicro, precisionMicro+recallMicro)
    precisionMacro := mean(precisions)
    recallMacro := mean(recalls)
    f1Macro := mean(f1s)
    precisionWeighted := weighted(precisions, supports)
    recallWeighted := weighted(recalls, supports)
    f1Weighted := weighted(f1s, supports)
    metrics := map[string]float64{
        "accuracy": accuracy,
        "precision_micro": precisionMicro,
        "recall_micro": recallMicro,
        "f1_micro": f1Micro,
        "precision_macro": precisionMacro,
        "recall_macro": recallMacro,
        "f1_macro": f1Macro,
        "precision_weighted": precisionWeighted,
        "recall_weighted": recallWeighted,
        "f1_weighted": f1Weighted,
    }
    return EvalResult{Metrics: metrics, MetricOrder: metricOrderForTask("multiclass_classification"), ConfusionMatrix: makeConfusionMatrix(preds, classes), PerClassMetrics: perClassMetrics}
}

func computeRegression(preds []NormPrediction) EvalResult {
    n := len(preds)
    actuals := make([]float64, n)
    predicted := make([]float64, n)
    for i, p := range preds {
        actuals[i] = p.ActualNum
        predicted[i] = p.PredictedNum
    }
    se := 0.0
    ae := 0.0
    smapeSum := 0.0
    smapeCount := 0
    for i := 0; i < n; i++ {
        diff := actuals[i] - predicted[i]
        se += diff * diff
        ae += math.Abs(diff)
        denom := math.Abs(actuals[i]) + math.Abs(predicted[i])
        if denom >= 1e-10 {
            smapeSum += 2 * math.Abs(diff) / denom
            smapeCount++
        }
    }
    mse := se / float64(n)
    rmse := math.Sqrt(mse)
    mae := ae / float64(n)
    meanActual := mean(actuals)
    ssRes := 0.0
    ssTot := 0.0
    for _, a := range actuals {
        ssTot += (a - meanActual) * (a - meanActual)
    }
    for i := range actuals {
        diff := actuals[i] - predicted[i]
        ssRes += diff * diff
    }
    rSquared := 0.0
    if ssTot != 0 {
        rSquared = 1 - ssRes/ssTot
    }
    smape := 0.0
    if smapeCount > 0 {
        smape = smapeSum / float64(smapeCount) * 100
    }
    metrics := map[string]float64{
        "mse": mse,
        "rmse": rmse,
        "mae": mae,
        "r_squared": rSquared,
        "smape": smape,
    }
    return EvalResult{Metrics: metrics, MetricOrder: metricOrderForTask("regression")}
}

func zeroMetrics(order []string) map[string]float64 {
    m := make(map[string]float64)
    for _, name := range order {
        m[name] = 0
    }
    return m
}
