func computeBootstrapCIs(taskType string, preds []NormPrediction, B int, confidence float64, rng *rand.Rand) map[string]CI {
    if B <= 0 {
        return nil
    }
    ciMetrics := ciMetricsForTask(taskType)
    if len(ciMetrics) == 0 {
        return nil
    }
    n := len(preds)
    values := make(map[string][]float64)
    for _, m := range ciMetrics {
        values[m] = make([]float64, 0, B)
    }
    for b := 0; b < B; b++ {
        resample := make([]NormPrediction, n)
        for i := 0; i < n; i++ {
            resample[i] = preds[rng.Intn(n)]
        }
        res := computeMetrics(taskType, resample)
        for _, m := range ciMetrics {
            values[m] = append(values[m], res.Metrics[m])
        }
    }
    cis := make(map[string]CI)
    for _, m := range ciMetrics {
        vals := values[m]
        sort.Float64s(vals)
        lowerIndex := clampIndex(int(math.Floor((1-confidence)/2*float64(B))), B)
        upperIndex := clampIndex(int(math.Floor((1+confidence)/2*float64(B)))-1, B)
        cis[m] = CI{Lower: round6(vals[lowerIndex]), Upper: round6(vals[upperIndex])}
    }
    return cis
}

func buildReportJSON(nm NormManifest, bootstrap int, confidence float64, seed int64) ReportJSON {
    report := ReportJSON{Model: nm.Model, Splits: make(map[string]SplitReportJSON)}
    var rng *rand.Rand
    if bootstrap > 0 {
        rng = rand.New(rand.NewSource(seed))
    }
    for _, ev := range nm.Evaluations {
        result := computeMetrics(nm.Model.TaskType, ev.Predictions)
        roundedMetrics := make(map[string]float64)
        for _, name := range result.MetricOrder {
            roundedMetrics[name] = round6(result.Metrics[name])
        }
        sr := SplitReportJSON{Dataset: ev.Dataset, Metrics: roundedMetrics}
        if nm.Model.TaskType != "regression" && result.ConfusionMatrix != nil {
            sr.ConfusionMatrix = result.ConfusionMatrix
        }
        if nm.Model.TaskType == "multiclass_classification" && len(result.PerClassMetrics) > 0 {
            sr.PerClassMetrics = make(map[string]PerClassMetric)
            for class, pm := range result.PerClassMetrics {
                sr.PerClassMetrics[class] = PerClassMetric{
                    Precision: round6(pm.Precision),
                    Recall:    round6(pm.Recall),
                    F1:        round6(pm.F1),
                    Support:   pm.Support,
                }
            }
        }
        if bootstrap > 0 {
            sr.ConfidenceIntervals = computeBootstrapCIs(nm.Model.TaskType, ev.Predictions, bootstrap, confidence, rng)
        }
        report.Splits[ev.Split] = sr
    }
    return report
}

