    for _, metric := range metricOrder {
        if _, ok := cfg.Thresholds[metric]; ok {
            cd.RegressionMetrics = append(cd.RegressionMetrics, metric)
        }
    }
    baseResults := make(map[string]EvalResult)
    candResults := make(map[string]EvalResult)
    for _, ev := range baseline.Evaluations {
        baseResults[ev.Split] = computeMetrics(taskType, ev.Predictions)
    }
    for _, ev := range candidate.Evaluations {
        candResults[ev.Split] = computeMetrics(taskType, ev.Predictions)
    }
    for _, split := range cd.SplitOrder {
        cd.Deltas[split] = make(map[string]DeltaEntry)
        for _, metric := range metricOrder {
            b := baseResults[split].Metrics[metric]
            c := candResults[split].Metrics[metric]
            abs := c - b
            var rel *float64
            if math.Abs(b) > 1e-10 {
                r := (c - b) / math.Abs(b)
                r = round6(r)
                rel = &r
            }
            cd.Deltas[split][metric] = DeltaEntry{
                Baseline:      round6(b),
                Candidate:     round6(c),
                AbsoluteDelta: round6(abs),
                RelativeDelta: rel,
            }
        }
    }
    criticalCount := 0
    warningCount := 0
    for _, metric := range cd.RegressionMetrics {
        t := cfg.Thresholds[metric]
        regressedSplits := []string{}
        for _, split := range cd.SplitOrder {
            b := baseResults[split].Metrics[metric]
            c := candResults[split].Metrics[metric]
            abs := c - b
            regressed := abs < t.MinAbsoluteDelta
            if !regressed && math.Abs(b) > 1e-10 {
                rel := (c - b) / math.Abs(b)
                if rel < t.MinRelativeDelta {
                    regressed = true
                }
            }
            if regressed {
                regressedSplits = append(regressedSplits, split)
            }
        }
        verdict := "PASS"
        if len(regressedSplits) > 0 {
            verdict = "REGRESSED"
            switch t.Severity {
            case "critical":
                criticalCount++
            case "warning":
                warningCount++
            }
        }
        cd.RegressionAnalysis[metric] = RegressionAnalysisEntry{
            Severity:        t.Severity,
            RegressedSplits: regressedSplits,
            Verdict:         verdict,
        }
    }
    cd.Overall.CriticalRegressions = criticalCount
    cd.Overall.WarningRegressions = warningCount
    if criticalCount > cfg.Rules.MaxCriticalRegressions || warningCount > cfg.Rules.MaxWarningRegressions {
        cd.Overall.Verdict = "FAIL"
    }
    return cd, nil
}

func buildComparisonMarkdown(cd ComparisonData) string {
    var b strings.Builder
    fmt.Fprintf(&b, "# Model Comparison Report\n\n")
    fmt.Fprintf(&b, "Baseline: %s v%s\n", cd.Baseline.Name, cd.Baseline.Version)
    fmt.Fprintf(&b, "Candidate: %s v%s\n", cd.Candidate.Name, cd.Candidate.Version)
    fmt.Fprintf(&b, "Task type: %s\n\n", cd.TaskType)
    fmt.Fprintf(&b, "## Performance Delta\n\n")
    fmt.Fprintln(&b, "| Metric | Split | Baseline | Candidate | Delta | Relative Delta |")
    fmt.Fprintln(&b, "|--------|-------|----------|-----------|-------|----------------|")
    for _, metric := range cd.MetricOrder {
        for _, split := range cd.SplitOrder {
            d := cd.Deltas[split][metric]
            rel := "N/A"
            if d.RelativeDelta != nil {
                rel = formatFloat2(*d.RelativeDelta*100) + "%"
            }
            fmt.Fprintf(&b, "| %s | %s | %s | %s | %s | %s |\n", metric, split, formatFloat6(d.Baseline), formatFloat6(d.Candidate), formatFloat6(d.AbsoluteDelta), rel)
        }
    }
    fmt.Fprintln(&b)
    fmt.Fprintf(&b, "## Regression Analysis\n\n")
    fmt.Fprintln(&b, "| Metric | Severity | Regressed Splits | Verdict |")
    fmt.Fprintln(&b, "|--------|----------|-----------------|---------|")
    for _, metric := range cd.RegressionMetrics {
        ra := cd.RegressionAnalysis[metric]
        splits := strings.Join(ra.RegressedSplits, ", ")
        fmt.Fprintf(&b, "| %s | %s | %s | %s |\n", metric, ra.Severity, splits, ra.Verdict)
    }
    fmt.Fprintln(&b)
    fmt.Fprintf(&b, "## Overall Verdict\n\n")
    fmt.Fprintf(&b, "Result: %s\n", cd.Overall.Verdict)
    fmt.Fprintf(&b, "Critical regressions: %d / %d\n", cd.Overall.CriticalRegressions, cd.Overall.MaxCriticalRegressions)
    fmt.Fprintf(&b, "Warning regressions: %d / %d\n", cd.Overall.WarningRegressions, cd.Overall.MaxWarningRegressions)
    return b.String()
}

func runCompare(args []string) int {
    fs := flag.NewFlagSet("compare", flag.ContinueOnError)
    baselinePath := fs.String("baseline", "", "path to baseline manifest")
    candidatePath := fs.String("candidate", "", "path to candidate manifest")
    configPath := fs.String("config", "", "path to regression config")
    outputDir := fs.String("output-dir", "", "directory for output files")
    format := fs.String("format", "both", "output format: md, json, or both")
    if err := fs.Parse(args); err != nil {
        fmt.Fprintln(os.Stderr, err)
        return 2
    }
    if *baselinePath == "" || *candidatePath == "" || *configPath == "" || *outputDir == "" {
        fmt.Fprintln(os.Stderr, "--baseline, --candidate, --config, and --output-dir are required")
        return 2
    }
    switch *format {
    case "md", "json", "both":
    default:
        fmt.Fprintf(os.Stderr, "invalid --format %q; must be md, json, or both\n", *format)
        return 2
    }
    baseline, err := loadManifest(*baselinePath)
    if err != nil {
        fmt.Fprintln(os.Stderr, err)
        return 2
    }
    candidate, err := loadManifest(*candidatePath)
    if err != nil {
        fmt.Fprintln(os.Stderr, err)
        return 2
    }
    cfg, err := loadRegressionConfig(*configPath)
    if err != nil {
        fmt.Fprintln(os.Stderr, err)
        return 2
    }
    cd, err := buildComparisonData(baseline, candidate, cfg)
    if err != nil {
        fmt.Fprintln(os.Stderr, err)
        return 2
    }
    if err := os.MkdirAll(*outputDir, 0755); err != nil {
        fmt.Fprintln(os.Stderr, err)
        return 2
    }
    if *format == "md" || *format == "both" {
        md := buildComparisonMarkdown(cd)
        if err := writeFile(filepath.Join(*outputDir, "comparison.md"), []byte(md)); err != nil {
            fmt.Fprintln(os.Stderr, err)
            return 2
        }
    }
    if *format == "json" || *format == "both" {
        data, err := json.MarshalIndent(cd, "", "  ")
        if err != nil {
            fmt.Fprintln(os.Stderr, err)
            return 2
        }
        if err := writeFile(filepath.Join(*outputDir, "comparison.json"), append(data, '\n')); err != nil {
            fmt.Fprintln(os.Stderr, err)
            return 2
        }
    }
    if cd.Overall.Verdict == "FAIL" {
        return 1
    }
    return 0
}

func main() {
    if len(os.Args) < 2 {
        fmt.Fprintln(os.Stderr, "usage: mlreport <evaluate|compare> ...")
        os.Exit(2)
    }
    var code int
    switch os.Args[1] {
    case "evaluate":
        code = runEvaluate(os.Args[2:])
    case "compare":
        code = runCompare(os.Args[2:])
    default:
        fmt.Fprintf(os.Stderr, "unknown command %q\n", os.Args[1])
        code = 2
    }
    os.Exit(code)
}
